/* pricing page: currency + period switches, checkout via licence server */
(function(){
  var ib=document.getElementById("prInt"),cb=document.getElementById("prCur");if(!ib||!cb)return;
  var cs=document.documentElement.getAttribute("data-site")==="cs",N=" ",TERMS="2026-10-19";
  var API="https://license.axion-cad.com/api/checkout";
  var P={start:{czk:[349,3490],eur:[14.9,149],usd:[15.9,159]},plus:{czk:[849,8490],eur:[34.9,349],usd:[37.9,379]},pro:{czk:[1549,15490],eur:[64.9,649],usd:[69.9,699]}};
  var T=cs?{m:"/"+N+"měsíc",y:"/"+N+"rok",bm:"Platba měsíčně, zrušení kdykoli",by:function(x){return "≈"+N+x+" měsíčně, platba ročně"},busy:"Přesměrovávám…",
      soon:"Online nákup spouštíme během několika dní. Mezitím nám napište na info@lmd-technologies.cz – licenci vám vystavíme hned.",err:"Platbu se nepodařilo zahájit. Zkuste to prosím znovu, případně napište na info@lmd-technologies.cz."}
    :{m:"/"+N+"month",y:"/"+N+"year",bm:"Billed monthly, cancel anytime",by:function(x){return "≈"+N+x+" a month, billed yearly"},busy:"Redirecting…",
      soon:"Online purchase opens in a few days. Meanwhile write to info@lmd-technologies.cz and we'll issue your licence right away.",err:"We couldn't start the payment. Please try again or write to info@lmd-technologies.cz."};
  function num(v,dec){var s=v.toFixed(dec);var p=s.split(".");p[0]=p[0].replace(/\B(?=(\d{3})+(?!\d))/g,cs?N:",");return p.join(cs?",":".")}
  function fmt(v,c){var dec=(c==="czk"||Math.round(v)===v)?0:2;var n=num(v,dec);
    if(c==="czk")return cs?n+N+"Kč":n+N+"CZK";
    if(c==="eur")return cs?n+N+"€":"€"+n;return cs?n+N+"$":"$"+n}
  function get(k){try{return localStorage.getItem(k)}catch(e){return null}}
  function put(k,v){try{localStorage.setItem(k,v)}catch(e){}}
  var tz="";try{tz=Intl.DateTimeFormat().resolvedOptions().timeZone||""}catch(e){}
  var cur=get("axion-cur")||(cs?"czk":(/^America\//.test(tz)||/-US$/i.test(navigator.language||"")?"usd":"eur"));
  var per="month";
  function seg(box,v){[].forEach.call(box.querySelectorAll("button"),function(b){b.setAttribute("aria-checked",b.getAttribute("data-v")===v?"true":"false")})}
  function draw(){seg(ib,per);seg(cb,cur);
    [].forEach.call(document.querySelectorAll(".plan[data-tier]"),function(el){var t=P[el.getAttribute("data-tier")][cur],y=per==="year";
      el.querySelector("[data-price]").textContent=fmt(y?t[1]:t[0],cur);el.querySelector("[data-per]").textContent=y?T.y:T.m;
      el.querySelector("[data-bill]").textContent=y?T.by(fmt(Math.round(t[1]/12*(cur==="czk"?1:100))/(cur==="czk"?1:100),cur)):T.bm})}
  ib.addEventListener("click",function(e){var b=e.target.closest("button");if(!b)return;per=b.getAttribute("data-v");draw()});
  cb.addEventListener("click",function(e){var b=e.target.closest("button");if(!b)return;cur=b.getAttribute("data-v");put("axion-cur",cur);draw()});
  draw();
  var key=(new URLSearchParams(location.search).get("key")||"").trim().toUpperCase();
  if(!/^AXN-[A-Z0-9-]{5,60}$/.test(key))key="";
  if(key){document.getElementById("prKey").hidden=false;document.getElementById("prKeyVal").textContent=key}
  var err=document.getElementById("prErr");
  document.addEventListener("click",function(e){var b=e.target.closest("[data-buy]");if(!b)return;e.preventDefault();
    var lab=b.querySelector("span"),old=lab.textContent,all=document.querySelectorAll("[data-buy]");err.hidden=true;
    [].forEach.call(all,function(x){x.disabled=true});lab.textContent=T.busy;
    var body={tier:b.getAttribute("data-buy"),interval:per,lang:cs?"cs":"en",terms:TERMS};if(key)body.key=key;
    fetch(API,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)})
      .then(function(r){return r.json().catch(function(){return {ok:false}})})
      .then(function(r){if(r&&r.ok&&r.url){location.href=r.url;return}
        err.textContent=(r&&r.error==="not_configured")?T.soon:T.err;err.hidden=false;throw 0})
      .catch(function(){if(err.hidden){err.textContent=T.err;err.hidden=false}[].forEach.call(all,function(x){x.disabled=false});lab.textContent=old});
  });
})();

/* thank-you page: confirm the Stripe checkout session */
(function(){
  var box=document.getElementById("ty");if(!box)return;
  var sid=new URLSearchParams(location.search).get("session_id")||"",n=0,NAMES={start:"Start",plus:"Plus",pro:"Pro"};
  function show(id){["tyWait","tyOk","tyNo"].forEach(function(x){document.getElementById(x).hidden=x!==id})}
  if(!/^cs_[A-Za-z0-9_]{10,200}$/.test(sid)){show("tyNo");return}
  (function poll(){n++;
    fetch("https://license.axion-cad.com/api/checkout/status?session_id="+encodeURIComponent(sid))
      .then(function(r){return r.json()}).then(function(r){
        if(r&&r.ok&&r.paid){document.getElementById("tyPlan").textContent=NAMES[r.tier]||"";var m=document.getElementById("tyMail");if(m)m.textContent=r.email||"";show("tyOk");return}
        if(n<8)setTimeout(poll,2500);else show("tyNo")})
      .catch(function(){if(n<8)setTimeout(poll,2500);else show("tyNo")});
  })();
})();
